-- -----------------------------------------------
-- SOURCE: 'migrations/023_add_steam_points_to_fellows.up.sql'
-- -----------------------------------------------

-- [LEGACY MIGRATION - CONSOLIDATED INTO 003]
-- This migration was consolidated into 003_create_fellows for fresh deployments.
-- It is retained here for backward compatibility with existing systems at version 23+
-- 
-- Original purpose: Add 501_steam_points column to fellows table for FR-27 contribution valuation
-- For fresh deployments: steam_points is created directly in migration 003
-- For existing systems: This migration provides upgrade path from pre-consolidated schemas

-- Idempotent: Only alter if column doesn't already exist
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name='fellows' AND column_name='steam_points'
    ) THEN
        ALTER TABLE fellows
        ADD COLUMN steam_points NUMERIC(10, 2) DEFAULT 0.0;
        
        CREATE INDEX idx_fellows_steam_points ON fellows (steam_points DESC);
    END IF;
END
$$;

-- -----------------------------------------------
-- SOURCE: 'migrations/024_refactor_fellow_applications.up.sql'
-- -----------------------------------------------

-- [LEGACY MIGRATION - CONSOLIDATED INTO 019 AND 003]
-- This migration was consolidated into 019_create_fellow_applications and 003_create_fellows for fresh deployments.
-- It is retained here for backward compatibility with existing systems.
--
-- Original purpose: Refactor fellow applications to use first_name/last_name instead of full_name,
-- add MOE identifier tracking, and add verification fields to fellows table.
-- For fresh deployments: All changes are part of 019 and 003 creation.
-- For existing systems: This migration provides upgrade path from pre-consolidated schemas.

-- Idempotent: Only migrate if full_name column still exists
DO $$
BEGIN
    -- Add new columns to fellow_applications if they don't exist
    IF EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name='fellow_applications' AND column_name='full_name'
    ) THEN
        ALTER TABLE fellow_applications
        ADD COLUMN IF NOT EXISTS first_name VARCHAR(100),
        ADD COLUMN IF NOT EXISTS last_name VARCHAR(100),
        ADD COLUMN IF NOT EXISTS moe_identifier VARCHAR(50),
        ADD COLUMN IF NOT EXISTS moe_doc_path TEXT;
        
        -- Migrate data from full_name to first_name and last_name
        UPDATE fellow_applications
        SET 
          first_name = CASE 
            WHEN full_name LIKE '% %' THEN SUBSTRING(full_name FROM 1 FOR POSITION(' ' IN full_name) - 1)
            ELSE full_name
          END,
          last_name = CASE 
            WHEN full_name LIKE '% %' THEN SUBSTRING(full_name FROM POSITION(' ' IN full_name) + 1)
            ELSE ''
          END
        WHERE first_name IS NULL OR last_name IS NULL;
        
        -- Provide default MOE identifiers for existing records
        UPDATE fellow_applications
        SET moe_identifier = 'MOE_' || application_id::text
        WHERE moe_identifier IS NULL;
        
        -- Make new columns NOT NULL (after migration)
        ALTER TABLE fellow_applications
        ALTER COLUMN first_name SET NOT NULL,
        ALTER COLUMN last_name SET NOT NULL,
        ALTER COLUMN moe_identifier SET NOT NULL;
        
        -- Drop full_name column after successful migration
        ALTER TABLE fellow_applications DROP COLUMN full_name;
        
        -- Add verification columns to fellows if they don't exist
        ALTER TABLE fellows
        ADD COLUMN IF NOT EXISTS source_application_id BIGINT,
        ADD COLUMN IF NOT EXISTS moe_identifier_verified BOOLEAN DEFAULT FALSE,
        ADD COLUMN IF NOT EXISTS verified_at TIMESTAMP,
        ADD COLUMN IF NOT EXISTS verified_by BIGINT;
        
        -- Add constraints if they don't exist
        ALTER TABLE fellows
        ADD CONSTRAINT IF NOT EXISTS fk_fellows_source_application
          FOREIGN KEY (source_application_id) REFERENCES fellow_applications(application_id) ON DELETE SET NULL,
        ADD CONSTRAINT IF NOT EXISTS fk_fellows_verified_by
          FOREIGN KEY (verified_by) REFERENCES users(user_id) ON DELETE SET NULL;
        
        -- Create indexes if they don't exist
        CREATE INDEX IF NOT EXISTS unique_pending_application_per_user
        ON fellow_applications(user_id)
        WHERE status = 'Pending';
        
        CREATE INDEX IF NOT EXISTS idx_fellows_verified ON fellows (moe_identifier_verified, verified_at);
        CREATE INDEX IF NOT EXISTS idx_fellow_applications_moe_doc_path ON fellow_applications (moe_doc_path);
    END IF;
END
$$;

-- -----------------------------------------------
-- SOURCE: 'migrations/025_subject_grade_level_pk_refactor.up.sql'
-- -----------------------------------------------

-- Consolidated Migration: 025_subject_grade_level_pk_refactor
-- Combines: 027_migrate_subject_grade_level_pks + 028_refactor_resource_subjects + 029_refactor_resource_grade_levels + 030_complete_pk_migration
-- Purpose: Refactor primary keys for subjects and grade_levels from VARCHAR to INTEGER
-- CRITICAL: This migration enables the ILO infrastructure which depends on subjects.id and grade_levels.id as INTEGER PKs

-- ============================================================================
-- Phase 1: Add new id columns to subjects and grade_levels (From 027)
-- ============================================================================
ALTER TABLE IF EXISTS subjects ADD COLUMN id SERIAL;
ALTER TABLE subjects ADD CONSTRAINT uq_subjects_id UNIQUE (id);

ALTER TABLE IF EXISTS grade_levels ADD COLUMN id SERIAL;
ALTER TABLE grade_levels ADD CONSTRAINT uq_grade_levels_id UNIQUE (id);

-- ============================================================================
-- Phase 2: Refactor resource_subjects to use subject_id (From 028)
-- ============================================================================
BEGIN;

-- Modify resource_subjects to use subject_id FK to subjects.id
ALTER TABLE resource_subjects DROP CONSTRAINT IF EXISTS resource_subjects_ibfk_2;
ALTER TABLE resource_subjects ADD COLUMN IF NOT EXISTS subject_id INT;

-- Populate subject_id based on subject lookup
UPDATE resource_subjects rs
SET subject_id = s.id
FROM subjects s
WHERE rs.subject = s.subject;

-- Add FK constraint if not already present
ALTER TABLE resource_subjects DROP COLUMN IF EXISTS subject CASCADE;
ALTER TABLE resource_subjects ADD CONSTRAINT fk_resource_subjects_subject_id 
    FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE CASCADE;

-- Create index
CREATE INDEX IF NOT EXISTS idx_resource_subjects_subject_id ON resource_subjects(subject_id);

